export const commerceProduct=id=>commerceProducts.find(p=>p.id===id);
export function productLinkAllowed(value,product){try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password&&!u.port&&product.hosts.includes(u.hostname.replace(/^www\./,''));}catch{return false;}}
